// Weights file for FSRCNNX 8-0-4-1 (igv, LGPL-3.0-or-later; see LICENSES/FSRCNNX-LGPL-3.0.txt): format check and parsing.
// The .bin is generated by scripts/fsrcnnx-extract.mjs; layout in fsrcnnx-layout.ts.
import { FSRCNNX_FLOAT_COUNT, FSRCNNX_HEADER_BYTES } from './fsrcnnx-layout';

/** Validates the byte length and returns the f32 payload (a copy, so it is 4-byte aligned regardless of the source). */
export function parseFsrcnnxWeights(buf: ArrayBuffer): Float32Array {
  const want = FSRCNNX_HEADER_BYTES + FSRCNNX_FLOAT_COUNT * 4;
  if (buf.byteLength !== want) throw new Error(`fsrcnnx weights: ${buf.byteLength} bytes, expected ${want} (regenerate with scripts/fsrcnnx-extract.mjs)`);
  const out = new Float32Array(FSRCNNX_FLOAT_COUNT);
  const dv = new DataView(buf, FSRCNNX_HEADER_BYTES);
  for (let i = 0; i < out.length; i++) out[i] = dv.getFloat32(i * 4, true);
  if (!out.every(Number.isFinite)) throw new Error('fsrcnnx weights: non-finite value');
  return out;
}
